def get_operation():
    """Get the arithmetic operation from user input."""
    operations = {
        "addition": "+",
        "subtraction": "-",
        "multiplication": "*",
        "division": "/"
    }

    while True:
        operation = input("Enter the arithmetic operation (addition, subtraction, multiplication, or division): ").lower()
        if operation in operations:
            return operation, operations[operation]
        else:
            print("Invalid operation. Please try again.")

def perform_operation(num1, num2, operation):
    """Perform the arithmetic operation on the two numbers."""
    if operation == "+":
        result = num1 + num2
    elif operation == "-":
        result = num1 - num2
    elif operation == "*":
        result = num1 * num2
    elif operation == "/":
        if num2 == 0:
            raise ValueError("Cannot divide by zero.")
        result = num1 / num2
    else:
        raise ValueError("Invalid operation.")

    return result

if __name__ == "__main__":
    num1 = float(input("Enter the first number: "))
    operation, operator = get_operation()
    num2 = float(input(f"Enter the second number ({operator} {num1}): "))

    try:
        result = perform_operation(num1, num2, operation)
        print(f"{num1} {operator} {num2} = {result}")
    except ValueError as e:
        print(e)
```

This program defines three functions: `get_operation()` to get the arithmetic operation from user input, `perform_operation()` to perform the arithmetic operation on the two numbers, and the main part of the program that calls these functions to get user input, perform the operation, and display the result.
